package com.chesspulseai.service; import com.chesspulseai.enumtype.*; import com.chesspulseai.exception.IllegalChessMoveException; import com.github.bhlangonijr.chesslib.*; import com.github.bhlangonijr.chesslib.move.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ChessPositionService { public record AppliedMove(String san,String fen,GameResult result) { public boolean completed(){return result!=GameResult.ONGOING;} } public AppliedMove apply(List<String> moves,String uci){Board b=new Board();for(String prior:moves)b.doMove(parseLegal(b,prior));Side mover=b.getSideToMove();Move move=parseLegal(b,uci);String san=san(b,move);b.doMove(move);GameResult result=GameResult.ONGOING;if(b.isMated()){san+="#";result=mover==Side.WHITE?GameResult.WHITE_WIN:GameResult.BLACK_WIN;}else if(b.isDraw())result=GameResult.DRAW;else if(b.isKingAttacked())san+="+";return new AppliedMove(san,b.getFen(),result);} private String san(Board b,Move m){Piece p=b.getPiece(m.getFrom());String from=m.getFrom().value().toLowerCase(Locale.ROOT),to=m.getTo().value().toLowerCase(Locale.ROOT);if(p.getPieceType()==PieceType.KING&&Math.abs(from.charAt(0)-to.charAt(0))==2)return to.charAt(0)=='g'?"O-O":"O-O-O";boolean capture=b.getPiece(m.getTo())!=Piece.NONE||(p.getPieceType()==PieceType.PAWN&&from.charAt(0)!=to.charAt(0));String prefix=p.getPieceType()==PieceType.PAWN?"":p.getSanSymbol();if(p.getPieceType()==PieceType.PAWN&&capture)prefix=from.substring(0,1);String promotion=m.getPromotion()==Piece.NONE?"":"="+m.getPromotion().getSanSymbol();return prefix+(capture?"x":"")+to+promotion;} private Move parseLegal(Board b,String u){try{Square from=Square.valueOf(u.substring(0,2).toUpperCase());Square to=Square.valueOf(u.substring(2,4).toUpperCase());Piece promotion=u.length()==5?promotion(b.getSideToMove(),u.charAt(4)):Piece.NONE;Move m=new Move(from,to,promotion);if(!b.legalMoves().contains(m))throw new IllegalChessMoveException("Move is not legal in the current position");return m;}catch(IllegalArgumentException|StringIndexOutOfBoundsException e){throw new IllegalChessMoveException("Move must be valid UCI notation");}} private Piece promotion(Side s,char c){return Piece.valueOf((s==Side.WHITE?"WHITE_":"BLACK_")+switch(Character.toUpperCase(c)){case 'Q'->"QUEEN";case 'R'->"ROOK";case 'B'->"BISHOP";case 'N'->"KNIGHT";default->throw new IllegalChessMoveException("Invalid promotion piece");});}}
